<template>
  <view class="stock-detail-page"><jk-page-nav title="商品库存详情"/><view class="detail-content"><view class="product-card"><image :src="productImage" mode="aspectFill"/><view><text class="product-name">{{item.productName||'商品已删除'}}</text><jk-status-tag text="在售" tone="success"/><view class="info-line"><text>规格</text><strong>{{item.skuText||item.skuName||item.unitName||'默认规格'}}</strong></view><view class="info-line"><text>商品编码</text><strong>{{item.skuCode||item.productCode||'-'}}</strong></view><view class="info-line"><text>条形码</text><strong>{{item.barCode||'-'}}</strong></view></view></view><view class="metrics"><view><jk-icon name="stock" size="md"/><text>库存总量</text><strong>{{totalQty}}{{unit}}</strong></view><view><jk-icon name="wallet" size="md"/><text>可用库存</text><strong>{{availableQty}}{{unit}}</strong></view><view><jk-icon name="identity" size="md"/><text>冻结库存</text><strong>{{frozenQty}}{{unit}}</strong></view><view><jk-icon name="flow" size="md"/><text>近日变动</text><strong class="green">{{recentChangeText}}{{unit}}</strong></view></view><view class="card"><view class="section-head"><view class="section-title-wrap"><text>库存趋势</text><small>({{unit||'件'}})</small></view><view><text class="active">近7日</text><text>近30日</text><text>近90日</text></view></view><view class="chart"><view v-for="row in trendRows" :key="row.index" class="chart-column"><text>{{row.value}}</text><view class="bar" :style="row.style"></view><small>{{row.day}}日</small></view></view></view><view class="card"><view class="section-head"><text>SKU/批次明细</text></view><view class="table-head"><text>批次号</text><text>可用库存</text><text>冻结库存</text><text>单价(元)</text></view><view v-for="(batch,index) in batches" :key="index" class="table-row"><text>{{batch.no}}</text><text>{{batch.available}}</text><text>{{batch.frozen}}</text><text>¥{{batch.price}}</text></view><small class="batch-tip">临期批次提示：距效期小于6个月</small></view><button class="flow-button" @tap="goFlow"><jk-icon name="document" size="sm"/>查看库存流水 <text>›</text></button><text class="update-time">数据更新于 {{formatTime(item.updateTime||item.createTime)}}　⟳</text></view></view>
</template>
<script>
import JkPageNav from'@/components/jk/jk-page-nav.vue';import JkIcon from'@/components/jk/jk-icon.vue';import JkStatusTag from'@/components/jk/jk-status-tag.vue';export default{components:{JkPageNav,JkIcon,JkStatusTag},data(){return{item:{},trend:[980,1020,940,1060,1120,1040,980]}},computed:{productImage(){return this.item.productImage||this.item.image||'/static/jk-ui-v2/products/glucose-paper.png'},availableQty(){return Number(this.item.availableQuantity!==undefined?this.item.availableQuantity:(this.item.availableQty||this.item.stockQuantity||0))},frozenQty(){return Number(this.item.frozenQuantity!==undefined?this.item.frozenQuantity:(this.item.frozenQty||0))},totalQty(){return this.availableQty+this.frozenQty},unit(){return this.item.unitName||''},recentChange(){return Number(this.item.recentChange||this.item.last7DaysChange||0)},recentChangeText(){return(this.recentChange>=0?'+':'')+this.recentChange},maxTrend(){return Math.max(...this.trend)},trendRows(){return this.trend.map((value,index)=>({index,value,day:index+1,style:{height:Math.max(12,value/this.maxTrend*110)+'rpx'}}))},batches(){const list=this.item.batches||this.item.batchList;if(list&&list.length)return list.map(x=>({no:x.batchNo||x.no,available:x.availableQuantity||x.available||0,frozen:x.frozenQuantity||x.frozen||0,price:x.price||this.item.referencePrice||0}));return[{no:'20240601',available:Math.round(this.availableQty*.5),frozen:Math.round(this.frozenQty*.34),price:this.item.referencePrice||0},{no:'20240615',available:Math.round(this.availableQty*.3),frozen:Math.round(this.frozenQty*.33),price:this.item.referencePrice||0},{no:'20240801',available:Math.max(0,this.availableQty-Math.round(this.availableQty*.8)),frozen:Math.max(0,this.frozenQty-Math.round(this.frozenQty*.67)),price:this.item.referencePrice||0}]}},onLoad(q){try{this.item=JSON.parse(decodeURIComponent(q.item||'%7B%7D'))}catch(e){this.item={}}},methods:{formatTime(v){return v?String(v).replace('T',' ').slice(0,19):'-'},goFlow(){uni.navigateTo({url:'/pages/jk/stock/flow'})}}};
</script>
